{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara plots a course into the ruined city.",
      "visual_description": "A windswept hill at dusk overlooking a shattered royal city; ink-stained coat flapping, brass compass spinning wildly, a parchment map weighted by stones.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp flickers a first warning.",
      "visual_description": "A close-up of an oil lamp on a stone wall; the flame holds a single glowing eye that stares toward the castle gates in the distance.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin fox scampers ahead to scout the gates.",
      "visual_description": "A small clockwork fox with a key-wind tail and blue glass eyes darting along the cracked cobblestones beneath looming, half-collapsed castle gates.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass diver emerges from a tall broken window.",
      "visual_description": "A figure in a clear diving helmet steps out of a shattered stained-glass window as if surfacing from water, coat catching reflections of broken neon-blue city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers beneath a torn royal banner.",
      "visual_description": "A frayed crimson banner sags across an alley; four figures huddle below it studying the map, the oracle lamp casting a warm orange circle on the stones.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower looms, humming with old magic.",
      "visual_description": "A leaning black tower wreathed in pale green mist; runes glow faintly along its base while the tin fox sniffs at a scorch mark on the ground.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number" : 7,
      "caption": "Rumor of a great winged beast above the rooftops.",
      "visual_description": "Silhouettes on a rooftop pointing at a vast shadow sliding across the moon; scales and a long tail just visible through smoke, but no creature shown clearly.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol clanks down the avenue.",
      "visual_description": "From a low alley angle, dented steel boots and pike-shafts march past a puddle; the tin fox crouches behind a barrel, eyes glowing dim to hide.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector blocks a key doorway.",
      "visual_description": "A plump official slumped on a stoop, ledger book under his head as a pillow, stamped papers stuck to his sleeves; a heavy oak door stands shut behind him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara forges a stamped pass from his own papers.",
      "visual_description": "Close-up of ink-stained fingers carefully peeling a wax-sealed pass off the dozing official's sleeve; the tin fox holds an inkpot in its jaws.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Oracle lamp warns of a deceitful magic door.",
      "visual_description": "An ornate door covered in shifting silver sigils; the lamp's single eye narrows, casting a warning red glow across the diver's reflective coat.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Glass diver slips through a tall mirror instead.",
      "visual_description": "A cracked floor-length mirror ripples like water as the diver plunges in headfirst, coat trailing shards of reflected lamplight.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Inside the keep, the captive is found at last.",
      "visual_description": "A dim stone chamber lit by the oracle lamp's beam; chains hang from a chair, and Mara's gloved hand reaches toward a small bundled figure off-frame.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Tin fox triggers a clockwork distraction.",
      "visual_description": "The metal fox winds its own tail and launches a cascade of bells and gears down a spiral stair; sparks bounce off ancient mosaic tiles.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Frightened townsfolk peer from shuttered windows.",
      "visual_description": "Narrow stone street lined with shuttered windows where pale faces and small lanterns peek out; Mara presses a finger to her lips as the team hurries past.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "An armored patrol blocks the route to the bridge.",
      "visual_description": "A line of polished helms across a plaza ahead; the diver crouches behind a fountain while the oracle lamp dims its flame to a thin orange thread.",
      "characters": ["glass_diver", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the cracked stone bridge.",
      "visual_description": "A long arched bridge over a churning black river; the team runs full tilt, the tin fox out front, banners and arrows flying past them in motion blur.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the lamp winks out one eye.",
      "visual_description": "Dawn light on a misty riverbank; the team rests against a milestone, the rescued bundle wrapped in Mara's coat as the oracle lamp's flame slowly closes its eye in relief.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

